#!/bin/bash
# 4-player expert iteration: generate -> train -> evaluate, for several rounds.
#   cbot/loop4.sh                      # env knobs below
#
# Env: P (workers/threads, default nproc), ROUNDS (default 4), FIRST (first round
# number, default 1), GAMES (games per round, default 30000), EVAL_GAMES (1000).
#
# Round r writes data/m<r>s, trains models/M<r> (3 nets at lam .5 + 3 at lam .3)
# on round 0 plus the last two rounds, and evaluates it vs three AlphaBetas on
# the fixed development seeds (20M). The next round is generated by the new
# ensemble unless it scores more than 3 points below the best so far (a sign of
# a broken round), in which case the best one keeps generating.
# State: models/BEST4.txt (ensemble spec), runs/best4_rate.txt, runs/loop4.jsonl.
# Rerunnable: finished generation (DONE marker) and training (models/M<r>.txt)
# are skipped.
set -euo pipefail
cd "$(dirname "$0")/.."
P=${P:-$(nproc)}
ROUNDS=${ROUNDS:-4}
FIRST=${FIRST:-1}
GAMES=${GAMES:-30000}
EVAL_GAMES=${EVAL_GAMES:-1000}
PY=.venv/bin/python
export PLAYERS=4

[ -f models/BEST4.txt ] || cp models/M0.txt models/BEST4.txt
[ -f runs/best4_rate.txt ] || echo 0.629 > runs/best4_rate.txt  # M0, full opening, seeds 20M

log() { echo "[$(date '+%F %T')] $*" | tee -a runs/loop4.log; }

for r in $(seq "$FIRST" $((FIRST + ROUNDS - 1))); do
  best=$(cat models/BEST4.txt)
  best_rate=$(cat runs/best4_rate.txt)
  out=data/m${r}s

  # 1. Generate with the current best bot (opening shortlist for speed).
  if [ ! -f "$out/DONE" ]; then
    log "round $r: generating $GAMES games into $out with $best"
    B="NN:$best:initf=2:openk=15"
    $PY -m cbot.gen --out "$out" --games "$GAMES" --procs "$P" --p-record 0.2 \
      --seed0 $((100000000 + r * 1000000)) --eps 0,0.03 --shard-games 1000 \
      --mix "$B,AB,AB,AB:4 $B,$B,AB,AB:2 $B,AB,AB,F:1 $B,$B,$B,$B:1" > "runs/gen_m${r}s.log" 2>&1
    touch "$out/DONE"
  fi

  # 2. Train on round 0 plus rounds r-1 and r (all data dirs for those rounds).
  if [ ! -f "models/M$r.txt" ]; then
    dirs=(data/m0 data/m0b)
    for k in $((r - 1)) "$r"; do
      if [ "$k" -lt 1 ]; then continue; fi
      for d in data/m${k} data/m${k}b data/m${k}s; do
        if [ -d "$d" ]; then dirs+=("$d"); fi
      done
    done
    log "round $r: training M$r on ${dirs[*]}"
    T=$(( P / 6 ))
    STAGGER=60 cbot/train_ens.sh "M${r}a" 3 0.5 "$T" "${dirs[@]}" > "runs/train_M${r}a.log" 2>&1 &
    sleep 30
    STAGGER=60 cbot/train_ens.sh "M${r}b" 3 0.3 "$T" "${dirs[@]}" > "runs/train_M${r}b.log" 2>&1 &
    wait
    echo "$(cat "models/M${r}a.txt")+$(cat "models/M${r}b.txt")" > "models/M$r.txt"
    log "round $r: val losses $(grep -h 'best val' runs/train_M${r}a_s*.log runs/train_M${r}b_s*.log | awk '{print $3}' | tr '\n' ' ')"
  fi

  # 3. Evaluate vs three AlphaBetas, full opening, development seeds.
  cand=$(cat "models/M$r.txt")
  $PY -m cbot.arena "NN:$cand:initf=2" AB AB AB --games "$EVAL_GAMES" --procs "$P" \
    --seed0 20000000 --log runs/loop4.jsonl > "runs/eval_M$r.log" 2>&1
  rate=$($PY -c 'import json,sys; print(json.loads(open("runs/loop4.jsonl").readlines()[-1])["a_winrate"])')
  log "round $r: M$r vs 3AB = $rate (best so far $best_rate) | $(tail -n 1 "runs/eval_M$r.log")"

  # 4. Next round's generator.
  if $PY -c "import sys; sys.exit(0 if $rate >= $best_rate - 0.03 else 1)"; then
    echo "$cand" > models/BEST4.txt
    $PY -c "print(max($rate, $best_rate))" > runs/best4_rate.txt
    log "round $r: M$r generates next"
  else
    log "round $r: M$r more than 3 points below best; keeping $(cat models/BEST4.txt)"
  fi
done
log "loop done"
